                    grecaptcha.enterprise.ready(function() {
                      grecaptcha.enterprise.execute(
                        mybooking_init_vars.mybooking_recaptcha_site_key,
                        {action: 'contact'}
                      ).then(function(token) {
                        contactModel.sendMessage(token);
                      });
                    });
