        // Append the id querystring
        if (theUrl.indexOf('?') > 0) {
          theUrl += '&';
        }
        else {
          theUrl += '?';
        }
        theUrl += 'id=';
        theUrl += bookingId;
        var parameters = {id: bookingId};
